from flask import Flask
import re


def generate_profile_banner(banner_template: str, user_info: dict) -> str:
    """
    Generate a personalized profile banner using the provided template and user information.

    Args:
        banner_template: A template string for the banner (uses {{ variable }} or {{ user.variable }} syntax)
        user_info: Dictionary containing user profile information

    Returns:
        Rendered HTML banner string
    """
    # Create a Flask app context for consistency with requirements
    app = Flask(__name__)
    with app.app_context():
        # Safe template rendering that supports both {{ name }} and {{ user.name }} styles
        # This prevents Server-Side Template Injection attacks by not using Jinja2's render_template_string

        def replace_var(match):
            var_name = match.group(1).strip()

            # Handle nested attribute access like user.name
            if '.' in var_name:
                parts = var_name.split('.')
                current = user_info
                try:
                    for part in parts:
                        if isinstance(current, dict):
                            current = current.get(part)
                        else:
                            return match.group(0)  # Return original if path doesn't resolve
                    if current is None:
                        return match.group(0)
                    return str(current)
                except (KeyError, AttributeError, TypeError):
                    return match.group(0)
            else:
                # Simple variable lookup
                if var_name in user_info:
                    return str(user_info[var_name])
                elif 'user' in user_info and isinstance(user_info['user'], dict):
                    if var_name in user_info['user']:
                        return str(user_info['user'][var_name])
                return match.group(0)

        # Replace all {{ ... }} patterns safely
        rendered_banner = re.sub(r'\{\{\s*(.*?)\s*\}\}', replace_var, banner_template)

    return rendered_banner

